pub fn check_p61970_600_2_dynamics_ap_con_simple_shacl_asynchronous_machine_equivalent_circuit_asynchron_etc(dataset: &CimDataset) -> Vec<Violation> {
    let mut violations = Vec::new();
    for mrid in dataset.by_type.get("AsynchronousMachineEquivalentCircuit").into_iter().flatten() {
        let entry = &dataset.entries[mrid];
        let obj = match entry.element.as_any()
            .downcast_ref::<cimstructs::AsynchronousMachineEquivalentCircuit>() {
            Some(o) => o, None => continue,
        };
        if obj.xlr1.is_none() {
            violations.push(Violation {
                object_id:   mrid.clone(),
                rule_id:     "dy:AsynchronousMachineEquivalentCircuit.xlr1-cardinality".to_string(),
                class:       "AsynchronousMachineEquivalentCircuit".to_string(),
                property:    "AsynchronousMachineEquivalentCircuit.xlr1".to_string(),
                message:     "Missing required property (attribute).".to_string(),
                severity:    "sh:Violation".to_string(),
                name:        "AsynchronousMachineEquivalentCircuit.xlr1-cardinality".to_string(),
                description: "This constraint validates the cardinality of the property (attribute).".to_string(),
            });
        }
    }
    violations
}

