pub fn check_p61970_600_2_dynamics_ap_con_simple_shacl_energy_consumer_energy_consumer_load_dynamics_in(dataset: &CimDataset) -> Vec<Violation> {
    let mut violations = Vec::new();
    for mrid in dataset.by_type.get("EnergyConsumer").into_iter().flatten() {
        let entry = &dataset.entries[mrid];
        let obj = match entry.element.as_any()
            .downcast_ref::<cimstructs::EnergyConsumer>() {
            Some(o) => o, None => continue,
        };
        let ref_mrid = match obj.load_dynamics.as_ref() {
            Some(r) => r.mrid.trim_start_matches('#'), None => continue,
        };
        if let Some(ref_entry) = dataset.entries.get(ref_mrid) {
            let allowed: &[&str] = &["LoadComposite", "LoadGenericNonLinear", "LoadAggregate", "LoadUserDefined"];
            if !allowed.contains(&ref_entry.element.type_name()) {
                violations.push(Violation {
                    object_id:   mrid.clone(),
                    rule_id:     "dy:EnergyConsumer.LoadDynamics-valueType".to_string(),
                    class:       "EnergyConsumer".to_string(),
                    property:    "EnergyConsumer.LoadDynamics".to_string(),
                    message:     "One of the following occurs: 1) The value type is not IRI; 2) The value type is not the right class.".to_string(),
                    severity:    "sh:Violation".to_string(),
                    name:        "EnergyConsumer.LoadDynamics-valueType".to_string(),
                    description: "This constraint validates the value type of the association at the used direction.".to_string(),
                });
            }
        }
    }
    violations
}

