pub fn check_p61970_600_2_dynamics_ap_con_simple_shacl_exc_rexs_exc_rexs_fbf_in(dataset: &CimDataset) -> Vec<Violation> {
    let mut violations = Vec::new();
    const ALLOWED: &[&str] = &["ExcREXSFeedbackSignalKind.fieldVoltage", "ExcREXSFeedbackSignalKind.fieldCurrent", "ExcREXSFeedbackSignalKind.outputVoltage"];
    for mrid in dataset.by_type.get("ExcREXS").into_iter().flatten() {
        let entry = &dataset.entries[mrid];
        let obj = match entry.element.as_any()
            .downcast_ref::<cimstructs::ExcREXS>() {
            Some(o) => o, None => continue,
        };
        if obj.fbf.is_none() { continue; }
        if !ALLOWED.contains(&obj.fbf.as_ref().map_or("", |u| u.uri.as_str())) {
            violations.push(Violation {
                object_id:   mrid.clone(),
                rule_id:     "dy:ExcREXS.fbf-datatype".to_string(),
                class:       "ExcREXS".to_string(),
                property:    "ExcREXS.fbf".to_string(),
                message:     "The datatype is not IRI (Internationalized Resource Identifier) or it is enumerated value not part of the profile.".to_string(),
                severity:    "sh:Violation".to_string(),
                name:        "ExcREXS.fbf-datatype".to_string(),
                description: "This constraint validates the datatype of the property (attribute).".to_string(),
            });
        }
    }
    violations
}

