pub fn check_p61970_600_2_dynamics_ap_con_simple_shacl_gov_ct2_gov_ct2_rselect_in(dataset: &CimDataset) -> Vec<Violation> {
    let mut violations = Vec::new();
    const ALLOWED: &[&str] = &["DroopSignalFeedbackKind.governorOutput", "DroopSignalFeedbackKind.electricalPower", "DroopSignalFeedbackKind.fuelValveStroke", "DroopSignalFeedbackKind.none"];
    for mrid in dataset.by_type.get("GovCT2").into_iter().flatten() {
        let entry = &dataset.entries[mrid];
        let obj = match entry.element.as_any()
            .downcast_ref::<cimstructs::GovCT2>() {
            Some(o) => o, None => continue,
        };
        if obj.rselect.is_none() { continue; }
        if !ALLOWED.contains(&obj.rselect.as_ref().map_or("", |u| u.uri.as_str())) {
            violations.push(Violation {
                object_id:   mrid.clone(),
                rule_id:     "dy:GovCT2.rselect-datatype".to_string(),
                class:       "GovCT2".to_string(),
                property:    "GovCT2.rselect".to_string(),
                message:     "The datatype is not IRI (Internationalized Resource Identifier) or it is enumerated value not part of the profile.".to_string(),
                severity:    "sh:Violation".to_string(),
                name:        "GovCT2.rselect-datatype".to_string(),
                description: "This constraint validates the datatype of the property (attribute).".to_string(),
            });
        }
    }
    violations
}

