pub fn check_p61970_600_2_dynamics_ap_con_simple_shacl_gov_hydro4_gov_hydro4_model_in(dataset: &CimDataset) -> Vec<Violation> {
    let mut violations = Vec::new();
    const ALLOWED: &[&str] = &["GovHydro4ModelKind.francisPelton", "GovHydro4ModelKind.simple", "GovHydro4ModelKind.kaplan"];
    for mrid in dataset.by_type.get("GovHydro4").into_iter().flatten() {
        let entry = &dataset.entries[mrid];
        let obj = match entry.element.as_any()
            .downcast_ref::<cimstructs::GovHydro4>() {
            Some(o) => o, None => continue,
        };
        if obj.model.is_none() { continue; }
        if !ALLOWED.contains(&obj.model.as_ref().map_or("", |u| u.uri.as_str())) {
            violations.push(Violation {
                object_id:   mrid.clone(),
                rule_id:     "dy:GovHydro4.model-datatype".to_string(),
                class:       "GovHydro4".to_string(),
                property:    "GovHydro4.model".to_string(),
                message:     "The datatype is not IRI (Internationalized Resource Identifier) or it is enumerated value not part of the profile.".to_string(),
                severity:    "sh:Violation".to_string(),
                name:        "GovHydro4.model-datatype".to_string(),
                description: "This constraint validates the datatype of the property (attribute).".to_string(),
            });
        }
    }
    violations
}

