pub fn check_p61970_600_2_dynamics_ap_con_simple_shacl_gov_hydro_francis_gov_hydro_francis_governor_cont_etc(dataset: &CimDataset) -> Vec<Violation> {
    let mut violations = Vec::new();
    const ALLOWED: &[&str] = &["FrancisGovernorControlKind.electromechanicalElectrohydraulic", "FrancisGovernorControlKind.mechanicHydraulicTransientFeedback", "FrancisGovernorControlKind.mechanicHydrolicTachoAccelerator"];
    for mrid in dataset.by_type.get("GovHydroFrancis").into_iter().flatten() {
        let entry = &dataset.entries[mrid];
        let obj = match entry.element.as_any()
            .downcast_ref::<cimstructs::GovHydroFrancis>() {
            Some(o) => o, None => continue,
        };
        if obj.governor_control.is_none() { continue; }
        if !ALLOWED.contains(&obj.governor_control.as_ref().map_or("", |u| u.uri.as_str())) {
            violations.push(Violation {
                object_id:   mrid.clone(),
                rule_id:     "dy:GovHydroFrancis.governorControl-datatype".to_string(),
                class:       "GovHydroFrancis".to_string(),
                property:    "GovHydroFrancis.governorControl".to_string(),
                message:     "The datatype is not IRI (Internationalized Resource Identifier) or it is enumerated value not part of the profile.".to_string(),
                severity:    "sh:Violation".to_string(),
                name:        "GovHydroFrancis.governorControl-datatype".to_string(),
                description: "This constraint validates the datatype of the property (attribute).".to_string(),
            });
        }
    }
    violations
}

