pub fn check_p61970_600_2_dynamics_ap_con_simple_shacl_load_generic_non_linear_load_generic_non_linear_g_etc(dataset: &CimDataset) -> Vec<Violation> {
    let mut violations = Vec::new();
    const ALLOWED: &[&str] = &["GenericNonLinearLoadModelKind.loadAdaptive", "GenericNonLinearLoadModelKind.exponentialRecovery"];
    for mrid in dataset.by_type.get("LoadGenericNonLinear").into_iter().flatten() {
        let entry = &dataset.entries[mrid];
        let obj = match entry.element.as_any()
            .downcast_ref::<cimstructs::LoadGenericNonLinear>() {
            Some(o) => o, None => continue,
        };
        if obj.generic_non_linear_load_model_type.is_none() { continue; }
        if !ALLOWED.contains(&obj.generic_non_linear_load_model_type.as_ref().map_or("", |u| u.uri.as_str())) {
            violations.push(Violation {
                object_id:   mrid.clone(),
                rule_id:     "dy:LoadGenericNonLinear.genericNonLinearLoadModelType-datatype".to_string(),
                class:       "LoadGenericNonLinear".to_string(),
                property:    "LoadGenericNonLinear.genericNonLinearLoadModelType".to_string(),
                message:     "The datatype is not IRI (Internationalized Resource Identifier) or it is enumerated value not part of the profile.".to_string(),
                severity:    "sh:Violation".to_string(),
                name:        "LoadGenericNonLinear.genericNonLinearLoadModelType-datatype".to_string(),
                description: "This constraint validates the datatype of the property (attribute).".to_string(),
            });
        }
    }
    violations
}

