pub fn check_p61970_600_2_dynamics_ap_con_simple_shacl_load_static_load_static_static_load_model_type_in(dataset: &CimDataset) -> Vec<Violation> {
    let mut violations = Vec::new();
    const ALLOWED: &[&str] = &["StaticLoadModelKind.exponential", "StaticLoadModelKind.zIP2", "StaticLoadModelKind.zIP1", "StaticLoadModelKind.constantZ"];
    for mrid in dataset.by_type.get("LoadStatic").into_iter().flatten() {
        let entry = &dataset.entries[mrid];
        let obj = match entry.element.as_any()
            .downcast_ref::<cimstructs::LoadStatic>() {
            Some(o) => o, None => continue,
        };
        if obj.static_load_model_type.is_none() { continue; }
        if !ALLOWED.contains(&obj.static_load_model_type.as_ref().map_or("", |u| u.uri.as_str())) {
            violations.push(Violation {
                object_id:   mrid.clone(),
                rule_id:     "dy:LoadStatic.staticLoadModelType-datatype".to_string(),
                class:       "LoadStatic".to_string(),
                property:    "LoadStatic.staticLoadModelType".to_string(),
                message:     "The datatype is not IRI (Internationalized Resource Identifier) or it is enumerated value not part of the profile.".to_string(),
                severity:    "sh:Violation".to_string(),
                name:        "LoadStatic.staticLoadModelType-datatype".to_string(),
                description: "This constraint validates the datatype of the property (attribute).".to_string(),
            });
        }
    }
    violations
}

