pub fn check_p61970_600_2_dynamics_ap_con_simple_shacl_mechanical_load_user_defined_mechanical_load_dyna_etc(dataset: &CimDataset) -> Vec<Violation> {
    let mut violations = Vec::new();
    for mrid in dataset.by_type.get("MechanicalLoadUserDefined").into_iter().flatten() {
        let entry = &dataset.entries[mrid];
        let obj = match entry.element.as_any()
            .downcast_ref::<cimstructs::MechanicalLoadUserDefined>() {
            Some(o) => o, None => continue,
        };
        let ref_mrid = match obj.base.asynchronous_machine_dynamics.as_ref() {
            Some(r) => r.mrid.trim_start_matches('#'), None => continue,
        };
        if let Some(ref_entry) = dataset.entries.get(ref_mrid) {
            let allowed: &[&str] = &["AsynchronousMachineEquivalentCircuit", "AsynchronousMachineTimeConstantReactance", "AsynchronousMachineUserDefined"];
            if !allowed.contains(&ref_entry.element.type_name()) {
                violations.push(Violation {
                    object_id:   mrid.clone(),
                    rule_id:     "dy:MechanicalLoadDynamics.AsynchronousMachineDynamics-valueType".to_string(),
                    class:       "MechanicalLoadUserDefined".to_string(),
                    property:    "MechanicalLoadDynamics.AsynchronousMachineDynamics".to_string(),
                    message:     "One of the following occurs: 1) The value type is not IRI; 2) The value type is not the right class.".to_string(),
                    severity:    "sh:Violation".to_string(),
                    name:        "MechanicalLoadDynamics.AsynchronousMachineDynamics-valueType".to_string(),
                    description: "This constraint validates the value type of the association at the used direction.".to_string(),
                });
            }
        }
    }
    violations
}

