pub fn check_p61970_600_2_dynamics_ap_con_simple_shacl_pss_ieee2b_pss_ieee2b_input_signal2type_in(dataset: &CimDataset) -> Vec<Violation> {
    let mut violations = Vec::new();
    const ALLOWED: &[&str] = &["InputSignalKind.busVoltage", "InputSignalKind.rotorSpeed", "InputSignalKind.fieldCurrent", "InputSignalKind.busFrequency", "InputSignalKind.generatorElectricalPower", "InputSignalKind.branchCurrent", "InputSignalKind.generatorAcceleratingPower", "InputSignalKind.busVoltageDerivative", "InputSignalKind.rotorAngularFrequencyDeviation", "InputSignalKind.busFrequencyDeviation", "InputSignalKind.generatorMechanicalPower"];
    for mrid in dataset.by_type.get("PssIEEE2B").into_iter().flatten() {
        let entry = &dataset.entries[mrid];
        let obj = match entry.element.as_any()
            .downcast_ref::<cimstructs::PssIEEE2B>() {
            Some(o) => o, None => continue,
        };
        if obj.input_signal2type.is_none() { continue; }
        if !ALLOWED.contains(&obj.input_signal2type.as_ref().map_or("", |u| u.uri.as_str())) {
            violations.push(Violation {
                object_id:   mrid.clone(),
                rule_id:     "dy:PssIEEE2B.inputSignal2Type-datatype".to_string(),
                class:       "PssIEEE2B".to_string(),
                property:    "PssIEEE2B.inputSignal2Type".to_string(),
                message:     "The datatype is not IRI (Internationalized Resource Identifier) or it is enumerated value not part of the profile.".to_string(),
                severity:    "sh:Violation".to_string(),
                name:        "PssIEEE2B.inputSignal2Type-datatype".to_string(),
                description: "This constraint validates the datatype of the property (attribute).".to_string(),
            });
        }
    }
    violations
}

