pub fn check_p61970_600_2_dynamics_ap_con_simple_shacl_wind_plant_user_defined_wind_plant_dynamics_remot_etc(dataset: &CimDataset) -> Vec<Violation> {
    let mut violations = Vec::new();
    for mrid in dataset.by_type.get("WindPlantUserDefined").into_iter().flatten() {
        let entry = &dataset.entries[mrid];
        let obj = match entry.element.as_any()
            .downcast_ref::<cimstructs::WindPlantUserDefined>() {
            Some(o) => o, None => continue,
        };
        let ref_mrid = match obj.base.remote_input_signal.as_ref() {
            Some(r) => r.mrid.trim_start_matches('#'), None => continue,
        };
        if let Some(ref_entry) = dataset.entries.get(ref_mrid) {
            let allowed: &[&str] = &["RemoteInputSignal"];
            if !allowed.contains(&ref_entry.element.type_name()) {
                violations.push(Violation {
                    object_id:   mrid.clone(),
                    rule_id:     "dy:WindPlantDynamics.RemoteInputSignal-valueType".to_string(),
                    class:       "WindPlantUserDefined".to_string(),
                    property:    "WindPlantDynamics.RemoteInputSignal".to_string(),
                    message:     "One of the following does not conform: 1) The value type shall be IRI; 2) The value type shall be an instance of the class: cim:RemoteInputSignal".to_string(),
                    severity:    "sh:Violation".to_string(),
                    name:        "WindPlantDynamics.RemoteInputSignal-valueType".to_string(),
                    description: "This constraint validates the value type of the association at the used direction.".to_string(),
                });
            }
        }
    }
    violations
}

